package cn.ping.launcher;
import android.app.*;import android.content.*;import android.content.pm.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;
public class HiddenAppsActivity extends Activity {
 final ExecutorService worker=Executors.newSingleThreadExecutor();android.content.SharedPreferences prefs;LinearLayout list;TextView count;EditText search;boolean dead,quick;final ArrayList<Entry> apps=new ArrayList<>();int ink=0xff1b3042,muted=0xff748596,accent=0xff397f7a;
 static class Entry{String pkg,label;ComponentName component;Drawable icon;}
 int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);return t;}
 GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);if(!HiddenVault.consume(getIntent().getStringExtra("ticket"))){startActivity(new Intent(this,HiddenGateActivity.class).putExtra("quick",getIntent().getBooleanExtra("quick",false)));finish();return;}quick=getIntent().getBooleanExtra("quick",false);prefs=getSharedPreferences("workspace",0);getWindow().setStatusBarColor(0xfff1f5f8);getWindow().setNavigationBarColor(0xfff1f5f8);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN|WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);
 LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xfff1f5f8);root.setFocusableInTouchMode(true);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});setContentView(root);root.requestApplyInsets();LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(dp(24),dp(12),dp(24),dp(4));TextView back=text("‹ 返回",16,ink);back.setPadding(0,dp(12),dp(16),dp(12));back.setOnClickListener(v->finish());top.addView(back,new LinearLayout.LayoutParams(0,-2,1));if(quick){TextView manage=text("管理",14,accent);manage.setPadding(dp(16),dp(12),0,dp(12));manage.setOnClickListener(v->{startActivity(new Intent(this,HiddenAppsActivity.class).putExtra("ticket",HiddenVault.grant()));finish();});top.addView(manage);}root.addView(top);
 TextView title=text(quick?"隐藏空间":"管理隐藏应用",28,ink);title.setTypeface(null,Typeface.BOLD);title.setPadding(dp(24),dp(8),dp(24),dp(6));root.addView(title);TextView intro=text(quick?"只属于你的应用入口":"开启开关后，从桌面与 Dock 隐藏",13,muted);intro.setPadding(dp(24),0,dp(24),dp(18));root.addView(intro);
 search=new EditText(this);search.setSingleLine();search.setTextSize(14);search.setTextColor(ink);search.setHintTextColor(muted);search.setHint("搜索应用");search.setPadding(dp(18),0,dp(18),0);search.setBackground(bg(Color.WHITE,16));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,dp(48));sp.setMargins(dp(20),0,dp(20),dp(12));root.addView(search,sp);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int n,int a){}public void onTextChanged(CharSequence s,int st,int before,int n){render();}public void afterTextChanged(Editable e){}});
 count=text("正在加载…",12,muted);count.setPadding(dp(24),0,dp(24),dp(12));root.addView(count);ScrollView scroll=new ScrollView(this);scroll.setVerticalScrollBarEnabled(false);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));list=new LinearLayout(this);list.setOrientation(1);list.setPadding(dp(16),0,dp(16),dp(24));scroll.addView(list);root.requestFocus();worker.execute(()->{PackageManager pm=getPackageManager();ArrayList<Entry> found=new ArrayList<>();HashSet<String> seen=new HashSet<>();for(ResolveInfo r:pm.queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER),0)){String pkg=r.activityInfo.packageName;if(pkg.equals(getPackageName())||!seen.add(pkg))continue;try{Entry e=new Entry();e.pkg=pkg;e.label=r.loadLabel(pm).toString();e.icon=r.loadIcon(pm);e.component=new ComponentName(pkg,r.activityInfo.name);found.add(e);}catch(RuntimeException ignored){}}java.text.Collator collator=java.text.Collator.getInstance(Locale.CHINA);found.sort((a,c)->collator.compare(a.label,c.label));runOnUiThread(()->{if(dead)return;apps.clear();apps.addAll(found);render();});});}
 void render(){if(list==null)return;list.removeAllViews();Set<String> hidden=prefs.getStringSet("hidden_packages",Collections.emptySet());String query=search.getText().toString().trim().toLowerCase(Locale.ROOT);ArrayList<Entry> visible=new ArrayList<>();int total=0;for(Entry e:apps){if(hidden.contains(e.pkg))total++;if((!quick||hidden.contains(e.pkg))&&(query.isEmpty()||e.label.toLowerCase(Locale.ROOT).contains(query)))visible.add(e);}count.setText(quick?"已解锁 · "+total+" 个隐藏应用":"已隐藏 "+total+" 个 · 更改立即生效");if(visible.isEmpty()){LinearLayout empty=new LinearLayout(this);empty.setOrientation(1);empty.setGravity(Gravity.CENTER);empty.setPadding(dp(24),dp(48),dp(24),dp(48));empty.addView(new AppActionPopup.Symbol(this,3,0xffa2b6bd),new LinearLayout.LayoutParams(dp(42),dp(42)));TextView hint=text(query.isEmpty()?"这里还没有隐藏应用":"没有找到匹配的应用",16,ink);hint.setGravity(Gravity.CENTER);hint.setPadding(0,dp(18),0,dp(8));empty.addView(hint);TextView sub=text(query.isEmpty()?"在管理页面添加，随时回来打开":"试试其他应用名称",12,muted);empty.addView(sub);list.addView(empty);return;}
 if(quick){int columns=Math.max(2,Math.min(5,getResources().getConfiguration().screenWidthDp/130));for(int i=0;i<visible.size();i+=columns){LinearLayout row=new LinearLayout(this);for(int j=0;j<columns;j++){if(i+j>=visible.size()){row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));continue;}Entry e=visible.get(i+j);LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setGravity(Gravity.CENTER);card.setPadding(dp(8),dp(16),dp(8),dp(12));card.setBackground(new RippleDrawable(android.content.res.ColorStateList.valueOf(0x18397f7a),bg(Color.WHITE,20),bg(Color.WHITE,20)));ImageView icon=new ImageView(this);icon.setImageDrawable(e.icon);card.addView(icon,new LinearLayout.LayoutParams(dp(50),dp(50)));TextView name=text(e.label,14,ink);name.setGravity(Gravity.CENTER);name.setMaxLines(2);name.setEllipsize(TextUtils.TruncateAt.END);name.setPadding(0,dp(12),0,0);card.addView(name,new LinearLayout.LayoutParams(-1,-2));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,dp(146),1);cp.setMargins(dp(5),dp(5),dp(5),dp(5));row.addView(card,cp);card.setContentDescription(e.label);card.setOnClickListener(v->launch(e));}list.addView(row);}}
 else for(Entry e:visible){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(16),dp(12),dp(16),dp(12));row.setBackground(bg(Color.WHITE,18));ImageView icon=new ImageView(this);icon.setImageDrawable(e.icon);row.addView(icon,new LinearLayout.LayoutParams(dp(42),dp(42)));LinearLayout labels=new LinearLayout(this);labels.setOrientation(1);TextView name=text(e.label,15,ink);name.setTypeface(null,Typeface.BOLD);name.setMaxLines(1);name.setEllipsize(TextUtils.TruncateAt.END);labels.addView(name);TextView status=text(hidden.contains(e.pkg)?"已隐藏":"桌面可见",12,muted);status.setPadding(0,dp(4),0,0);labels.addView(status);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.leftMargin=dp(12);row.addView(labels,lp);Switch toggle=new Switch(this);toggle.setContentDescription("隐藏 "+e.label);toggle.setThumbTintList(android.content.res.ColorStateList.valueOf(accent));toggle.setChecked(hidden.contains(e.pkg));row.addView(toggle);toggle.setOnCheckedChangeListener((v,on)->{HashSet<String> next=new HashSet<>(prefs.getStringSet("hidden_packages",Collections.emptySet()));if(on)next.add(e.pkg);else next.remove(e.pkg);prefs.edit().putStringSet("hidden_packages",next).apply();status.setText(on?"已隐藏":"桌面可见");int n=0;for(Entry a:apps)if(next.contains(a.pkg))n++;count.setText("已隐藏 "+n+" 个 · 更改立即生效");});LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.setMargins(dp(4),0,dp(4),dp(10));list.addView(row,rp);}}
 void launch(Entry e){if(prefs.getLong("pause_"+e.pkg,0)>System.currentTimeMillis()){new AlertDialog.Builder(this).setTitle("此应用已暂停").setMessage("是否恢复从本桌面打开？").setNegativeButton("取消",null).setPositiveButton("恢复",(dialog,n)->{prefs.edit().remove("pause_"+e.pkg).apply();launch(e);}).show();return;}try{startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setComponent(e.component).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_RESET_TASK_IF_NEEDED));finish();}catch(RuntimeException ex){Toast.makeText(this,"应用暂时无法打开",0).show();}}
 protected void onStop(){super.onStop();if(!isFinishing())finish();}
 public void onDestroy(){dead=true;worker.shutdownNow();super.onDestroy();}
}
